// Independent SQL job source proves acceptance != fulfillment and retries never duplicate writes.
// 独立SQL任务源证明受理不等于履约，恢复不能重复写入。
import assert from 'node:assert/strict';import {randomUUID} from 'node:crypto';import {mkdtemp,rm} from 'node:fs/promises';import {resolve,join} from 'node:path';import {z} from 'zod';
import {openDatabase,withEnterprise,type Database} from '../../src/db/adapter.ts';import {migrate} from '../../src/db/migrate.ts';import {ProcessRegistry} from '../../src/connectors/process-registry.ts';import {GraphService} from '../../src/runtime/graph-service.ts';import {GraphToolCatalog,type GraphTool} from '../../src/runtime/graph-contracts.ts';import {hash} from '../../src/runtime/contracts.ts';
export const name={zh:'受控工作',en:'Controlled work',ja:'制御された作業'};
export const definition=(id='flow')=>JSON.stringify({format:'enterprise-brain.process/1',id,revision:'one',name,kind:'workflow_definition',roles:[{id:'owner',name}],objects:[{id:'order',name}],nodes:[{id:'start',name,kind:'start',ownerRole:'owner',objectRefs:[]},{id:'work',name,kind:'task',ownerRole:'owner',objectRefs:['order']},{id:'end',name,kind:'end',ownerRole:'owner',objectRefs:[]}],edges:[{id:'a',from:'start',to:'work'},{id:'b',from:'work',to:'end'}]});
export async function fixture(location=':memory:'){
 const db=await openDatabase(location),source=await openDatabase(':memory:');await migrate(db,'migrations');await source.exec('CREATE TABLE jobs(reference uuid PRIMARY KEY,args_hash text NOT NULL,state text NOT NULL,value integer NOT NULL)');const enterpriseId=randomUUID(),actors:any={};await db.query("INSERT INTO enterprise VALUES($1,'Graph','demo','CNY','Asia/Shanghai')",[enterpriseId]);for(const role of ['it','executive','operations','auditor']){const id=randomUUID();await db.query('INSERT INTO principal(id,enterprise_id,username,role) VALUES($1,$2,$3,$4)',[id,enterpriseId,role,role]);actors[role]={id,enterpriseId,role,authorizationVersion:1};}
 const state={now:new Date('2026-10-15T02:00:00Z'),calls:0,lookups:0,authorized:true,drop:false,partial:false,gate:null as Promise<void>|null,onAuthorize:null as (()=>Promise<void>)|null,onSubmit:null as (()=>void)|null};
 const result=async(reference:string)=>{const r=(await source.query<any>('SELECT * FROM jobs WHERE reference=$1',[reference])).rows[0];return {reference,state:r?.state??'missing',receiptRef:r?'owned-'+reference:null,sourceRevision:r?'source-one':null,data:r?{value:r.value}:{}};};
 const tool:GraphTool={id:'owned.job',version:'v1',effect:'delegated',validate:a=>z.object({value:z.number().int().positive().max(100)}).strict().parse(a),async authorize(){if(state.onAuthorize)await state.onAuthorize();if(!state.authorized)throw Error('source_not_authorized');},async submit(_actor,args,reference){state.calls++;await source.query("INSERT INTO jobs VALUES($1,$2,'accepted',$3) ON CONFLICT DO NOTHING",[reference,hash(args),args.value]);assert.equal((await source.query<any>('SELECT args_hash FROM jobs WHERE reference=$1',[reference])).rows[0].args_hash,hash(args));state.onSubmit?.();if(state.gate)await state.gate;if(state.drop)throw Error('response_lost_after_acceptance');return result(reference);},async lookup(_actor,_args,reference){state.lookups++;return result(reference);}};
 const catalog=new GraphToolCatalog([tool]),service=new GraphService(db,catalog,()=>state.now,100),registry=new ProcessRegistry(db,process.cwd());
 async function add(id='flow'){const r=await registry.import(actors.it,{sourceId:'owned',expectedVersion:0,origin:'operator_import',content:definition(id)});return registry.confirm(actors.it,r.id,{expectedVersion:r.version,rawSha256:r.rawSha256,definitionSha256:r.definitionSha256,mapping:[{stageId:'procure-1',nodeId:'work'}],semanticsAcknowledged:true});}
 async function plan(id='flow'){const s=await add(id),input={processes:[{id:s.id,expectedVersion:s.version}],links:[],routes:[],bindings:[{processId:s.id,nodeId:'work',toolId:tool.id,toolVersion:tool.version,args:{value:10}}]},p=await service.compile(actors.it,input);return {s,input,p};}
 async function start(p:any,key:string=randomUUID()){const a=await service.approve(actors.executive,p.id,{planHash:p.planHash,executionAcknowledged:true}),r=await service.create(actors.operations,p.id,{approvalId:a.id,idempotencyKey:key});return {a,r};}
 return {db,source,actors,state,tool,catalog,service,registry,add,plan,start,result,async fulfill(ref:string,status='completed'){await source.query('UPDATE jobs SET state=$2 WHERE reference=$1',[ref,status]);},async close(){await source.close();await db.close();}};
}
